struct Clip {const char*name;unsigned first,count;};
inline const Clip Clips[]={
{"cidle13",0,76},
{"cidle14",76,76},
{"cidle21",152,83},
};
inline double Weight(const std::string&name,const std::array<M,15>&game){
 const Clip*clip=nullptr;for(const auto&c:Clips)if(name==c.name){clip=&c;break;}if(!clip)return 0;
 constexpr unsigned drivers[]={1,2,3,4,5,6,7,8};double features[72];unsigned k=0;M root=Inverse(game[0]);
 for(unsigned driver:drivers){M local=Product(root,game[driver]);for(unsigned i=0;i<3;++i)for(unsigned j=0;j<3;++j)features[k++]=local.r[i][j];}
 double best=1e100,chosen=0;unsigned segment=0;
 for(unsigned i=0;i+1<clip->count;++i){const auto&a=Frames[clip->first+i];const auto&b=Frames[clip->first+i+1];double length=0,dot=0;
  for(unsigned j=0;j<72;++j){double delta=b.features[j]-a.features[j];length+=delta*delta;dot+=(features[j]-a.features[j])*delta;}
  double t=length>1e-16?std::clamp(dot/length,0.,1.):0,error=0;
  for(unsigned j=0;j<72;++j){double delta=features[j]-((1-t)*a.features[j]+t*b.features[j]);error+=delta*delta;}
  if(error<best){best=error;segment=i;chosen=t;}
 }
 const auto&a=Frames[clip->first+segment];const auto&b=Frames[clip->first+segment+1];return (1-chosen)*a.weight+chosen*b.weight;
}
